(function (global) {
  "use strict";

  const MODE_BYTE = 4;
  const PAD0 = 0xec;
  const PAD1 = 0x11;

  const EXP = new Uint8Array(512);
  const LOG = new Uint8Array(256);

  (function initTables() {
    let x = 1;
    for (let i = 0; i < 255; i++) {
      EXP[i] = x;
      LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11d;
    }
    for (let i = 255; i < 512; i++) {
      EXP[i] = EXP[i - 255];
    }
  })();

  function gMul(a, b) {
    return a === 0 || b === 0 ? 0 : EXP[(LOG[a] + LOG[b]) % 255];
  }

  function rsPoly(ecLen) {
    let poly = [1];
    for (let i = 0; i < ecLen; i++) {
      const next = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gMul(poly[j], EXP[i]);
      }
      poly = next;
    }
    return poly;
  }

  function rsEncode(data, ecLen) {
    const gen = rsPoly(ecLen);
    const buf = data.concat(new Array(ecLen).fill(0));
    for (let i = 0; i < data.length; i++) {
      const factor = buf[i];
      if (factor !== 0) {
        for (let j = 0; j < gen.length; j++) {
          buf[i + j] ^= gMul(gen[j], factor);
        }
      }
    }
    return buf.slice(data.length);
  }

  // Tabelas para versões 1 a 10 (Nível M)
  const VER_META = [
    null,
    { totalDc: 16, ecPerBlock: 10, blocks: [[1, 16]] },
    { totalDc: 28, ecPerBlock: 16, blocks: [[1, 28]] },
    { totalDc: 44, ecPerBlock: 26, blocks: [[1, 44]] },
    { totalDc: 64, ecPerBlock: 18, blocks: [[2, 32]] },
    { totalDc: 86, ecPerBlock: 24, blocks: [[2, 43]] },
    { totalDc: 108, ecPerBlock: 16, blocks: [[4, 27]] },
    { totalDc: 124, ecPerBlock: 18, blocks: [[4, 31]] },
    {
      totalDc: 154,
      ecPerBlock: 22,
      blocks: [
        [2, 38],
        [2, 39],
      ],
    },
    {
      totalDc: 182,
      ecPerBlock: 22,
      blocks: [
        [3, 36],
        [2, 37],
      ],
    },
    {
      totalDc: 216,
      ecPerBlock: 26,
      blocks: [
        [4, 43],
        [1, 44],
      ],
    },
  ];

  const ALIGN_POS = [
    null,
    [],
    [6, 18],
    [6, 22],
    [6, 26],
    [6, 30],
    [6, 34],
    [6, 22, 38],
    [6, 24, 42],
    [6, 26, 46],
    [6, 28, 50],
  ];

  function escolherVersao(byteLen) {
    for (let v = 1; v <= 10; v++) {
      const ccBits = v <= 9 ? 8 : 16;
      const maxBits = VER_META[v].totalDc * 8;
      const neededBits = 4 + ccBits + byteLen * 8;
      if (neededBits <= maxBits) return v;
    }
    throw new Error("Texto demasiado longo para QR Code até versão 10.");
  }

  function construirDataCodewords(bytes, version) {
    const meta = VER_META[version];
    const ccBits = version <= 9 ? 8 : 16;
    const maxBits = meta.totalDc * 8;
    const bits = [];

    function push(val, len) {
      for (let i = len - 1; i >= 0; i--) {
        bits.push((val >>> i) & 1);
      }
    }

    push(MODE_BYTE, 4);
    push(bytes.length, ccBits);
    for (let i = 0; i < bytes.length; i++) push(bytes[i], 8);

    const term = Math.min(4, maxBits - bits.length);
    if (term > 0) push(0, term);

    while (bits.length % 8 !== 0) bits.push(0);

    let padIdx = 0;
    while (bits.length < maxBits) {
      push(padIdx % 2 === 0 ? PAD0 : PAD1, 8);
      padIdx++;
    }

    const out = [];
    for (let i = 0; i < maxBits; i += 8) {
      let b = 0;
      for (let j = 0; j < 8; j++) b = (b << 1) | bits[i + j];
      out.push(b);
    }
    return out;
  }

  function intercalar(dc, version) {
    const meta = VER_META[version];
    const dataBlocks = [];
    const ecBlocks = [];
    let offset = 0;

    for (const [count, len] of meta.blocks) {
      for (let b = 0; b < count; b++) {
        const slice = dc.slice(offset, offset + len);
        offset += len;
        dataBlocks.push(slice);
        ecBlocks.push(rsEncode(slice, meta.ecPerBlock));
      }
    }

    const finalStream = [];
    const maxDataLen = Math.max(...dataBlocks.map((x) => x.length));
    for (let i = 0; i < maxDataLen; i++) {
      for (const blk of dataBlocks) {
        if (i < blk.length) finalStream.push(blk[i]);
      }
    }
    for (let i = 0; i < meta.ecPerBlock; i++) {
      for (const blk of ecBlocks) {
        if (i < blk.length) finalStream.push(blk[i]);
      }
    }
    return finalStream;
  }

  function bchFormat(ecLevelBits, mask) {
    const data = ((ecLevelBits & 3) << 3) | (mask & 7);
    let d = data << 10;
    const poly = 0x537;
    for (let i = 4; i >= 0; i--) {
      if ((d >>> (i + 10)) & 1) {
        d ^= poly << i;
      }
    }
    return ((data << 10) | d) ^ 0x5412;
  }

  function aplicarMascara(mask, r, c) {
    switch (mask) {
      case 0:
        return (r + c) % 2 === 0;
      case 1:
        return r % 2 === 0;
      case 2:
        return c % 3 === 0;
      case 3:
        return (r + c) % 3 === 0;
      case 4:
        return (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0;
      case 5:
        return ((r * c) % 2) + ((r * c) % 3) === 0;
      case 6:
        return (((r * c) % 2) + ((r * c) % 3)) % 2 === 0;
      case 7:
        return (((r + c) % 2) + ((r * c) % 3)) % 2 === 0;
      default:
        return false;
    }
  }

  function penalidade(grid) {
    const n = grid.length;
    let score = 0;

    for (let r = 0; r < n; r++) {
      let run = 1;
      for (let c = 1; c < n; c++) {
        if (grid[r][c] === grid[r][c - 1]) {
          run++;
        } else {
          if (run >= 5) score += 3 + (run - 5);
          run = 1;
        }
      }
      if (run >= 5) score += 3 + (run - 5);
    }

    for (let c = 0; c < n; c++) {
      let run = 1;
      for (let r = 1; r < n; r++) {
        if (grid[r][c] === grid[r - 1][c]) {
          run++;
        } else {
          if (run >= 5) score += 3 + (run - 5);
          run = 1;
        }
      }
      if (run >= 5) score += 3 + (run - 5);
    }

    for (let r = 0; r < n - 1; r++) {
      for (let c = 0; c < n - 1; c++) {
        const v = grid[r][c];
        if (
          v === grid[r][c + 1] &&
          v === grid[r + 1][c] &&
          v === grid[r + 1][c + 1]
        ) {
          score += 3;
        }
      }
    }

    return score;
  }

  function gerarMatriz(texto) {
    const bytes = Array.from(new TextEncoder().encode(texto));
    const version = escolherVersao(bytes.length);
    const dc = intercalar(construirDataCodewords(bytes, version), version);
    const size = version * 4 + 17;

    const base = Array.from({ length: size }, () => new Array(size).fill(null));
    const isFunc = Array.from({ length: size }, () =>
      new Array(size).fill(false),
    );

    function setFunc(r, c, dark) {
      if (r >= 0 && r < size && c >= 0 && c < size) {
        base[r][c] = dark ? 1 : 0;
        isFunc[r][c] = true;
      }
    }

    function finder(r0, c0) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const dark =
            r >= 0 &&
            r <= 6 &&
            c >= 0 &&
            c <= 6 &&
            (r === 0 ||
              r === 6 ||
              c === 0 ||
              c === 6 ||
              (r >= 2 && r <= 4 && c >= 2 && c <= 4));
          setFunc(r0 + r, c0 + c, dark);
        }
      }
    }

    finder(0, 0);
    finder(0, size - 7);
    finder(size - 7, 0);

    const align = ALIGN_POS[version] || [];
    for (const rCenter of align) {
      for (const cCenter of align) {
        if (isFunc[rCenter][cCenter]) continue;
        for (let dr = -2; dr <= 2; dr++) {
          for (let dc = -2; dc <= 2; dc++) {
            const d = Math.max(Math.abs(dr), Math.abs(dc));
            setFunc(rCenter + dr, cCenter + dc, d === 0 || d === 2);
          }
        }
      }
    }

    for (let i = 8; i < size - 8; i++) {
      setFunc(6, i, i % 2 === 0);
      setFunc(i, 6, i % 2 === 0);
    }

    setFunc(size - 8, 8, true);

    // Reservar áreas de formato
    for (let i = 0; i < 9; i++) {
      isFunc[8][i] = true;
      isFunc[i][8] = true;
    }
    for (let i = 0; i < 8; i++) {
      isFunc[8][size - 1 - i] = true;
      isFunc[size - 1 - i][8] = true;
    }

    const bits = [];
    for (const cw of dc) {
      for (let b = 7; b >= 0; b--) bits.push((cw >>> b) & 1);
    }

    let bestGrid = null;
    let bestScore = Infinity;

    for (let mask = 0; mask < 8; mask++) {
      const grid = base.map((row) => row.slice());
      let idx = 0;
      let up = true;

      for (let col = size - 1; col >= 1; col -= 2) {
        if (col === 6) col = 5;
        for (let step = 0; step < size; step++) {
          const row = up ? size - 1 - step : step;
          for (const c of [col, col - 1]) {
            if (!isFunc[row][c]) {
              const bit = idx < bits.length ? bits[idx++] : 0;
              const dark = aplicarMascara(mask, row, c) ? bit ^ 1 : bit;
              grid[row][c] = dark;
            }
          }
        }
        up = !up;
      }

      // Nível M -> bits 00
      const fmt = bchFormat(0, mask);
      const topLeftCoords = [
        [0, 8],
        [1, 8],
        [2, 8],
        [3, 8],
        [4, 8],
        [5, 8],
        [7, 8],
        [8, 8],
        [8, 7],
        [8, 5],
        [8, 4],
        [8, 3],
        [8, 2],
        [8, 1],
        [8, 0],
      ];
      for (let i = 0; i < 15; i++) {
        const bit = (fmt >>> (14 - i)) & 1;
        const [r, c] = topLeftCoords[i];
        grid[r][c] = bit;
      }
      for (let i = 0; i < 8; i++) {
        const bit = (fmt >>> (14 - i)) & 1;
        grid[size - 1 - i][8] = bit;
      }
      for (let i = 0; i < 7; i++) {
        const bit = (fmt >>> (6 - i)) & 1;
        grid[8][size - 7 + i] = bit;
      }

      const sc = penalidade(grid);
      if (sc < bestScore) {
        bestScore = sc;
        bestGrid = grid;
      }
    }

    return bestGrid;
  }

  function toCanvas(canvas, texto, opts, cb) {
    const options = Object.assign(
      { width: 220, margin: 2, color: { dark: "#000000", light: "#ffffff" } },
      opts || {},
    );
    try {
      const grid = gerarMatriz(String(texto || ""));
      const ctx = canvas.getContext("2d");
      const quiet = Number(options.margin) || 2;
      const total = grid.length + quiet * 2;
      const cell = Math.max(2, Math.floor(canvas.width / total));
      const drawn = cell * total;
      const ox = Math.floor((canvas.width - drawn) / 2);
      const oy = Math.floor((canvas.height - drawn) / 2);

      ctx.fillStyle = (options.color && options.color.light) || "#ffffff";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = (options.color && options.color.dark) || "#000000";
      for (let r = 0; r < grid.length; r++) {
        for (let c = 0; c < grid.length; c++) {
          if (grid[r][c] === 1) {
            ctx.fillRect(
              ox + (c + quiet) * cell,
              oy + (r + quiet) * cell,
              cell,
              cell,
            );
          }
        }
      }
      if (typeof cb === "function") cb(null, canvas);
    } catch (err) {
      if (typeof cb === "function") cb(err);
      else console.error(err);
    }
  }

  global.QRCode = { toCanvas };
})(window);
